<script setup lang="ts">
import { computed, nextTick, onMounted, onBeforeUnmount, ref, watch } from 'vue';
import { api, errorText, session, mutationId } from '../api';
import type { PhotoLibrary, PhotoMemory } from '../../../packages/contracts/src/index.js';
import { groupPhotos, photoGroupKey, photoDate, photoPlaceName } from '../photos';
import AtlasIcon from '../components/AtlasIcon.vue';
import ModalSheet from '../components/ModalSheet.vue';
import PhotoViewer from '../components/PhotoViewer.vue';
import PhotoEditor from '../components/PhotoEditor.vue';
import PhotoMemoryMap from '../components/PhotoMemoryMap.vue';
import '../styles/photo-memories.css';
const library = ref<PhotoLibrary>({ items: [], groupNotes: [] }), busy = ref(false), error = ref(''), mode = ref<'list' | 'map'>('list'), year = ref('all'), place = ref('all'), filter = ref<'year' | 'place' | null>(null);
const content = ref<HTMLElement>(), editor = ref(false), editing = ref<PhotoMemory>(), viewer = ref<{ photos: PhotoMemory[]; start: string } | null>(null), mapFocus = ref<PhotoMemory | null>(null), mapSeen = ref(false);
let scroll = 0, disposed = false;
const removing = ref<PhotoMemory | null>(null), removeBusy = ref(false), removeError = ref(''); let removeKey = mutationId();
async function removePhoto() { if (!removing.value || removeBusy.value) return; removeBusy.value = true; removeError.value = ''; try { await api('/photos/' + removing.value.mediaId, 'DELETE', { baseVersion: removing.value.baseVersion, clientMutationId: removeKey }); removing.value = null; viewer.value = null; await load(); } catch (e) { removeError.value = errorText(e); } finally { removeBusy.value = false; } }
const stateKey = 'atlas-photo-browse:v1:' + session.value?.user.id;
const filtered = computed(() => library.value.items.filter(p => (year.value === 'all' || (year.value === 'unknown' ? !p.takenOn : p.takenOn?.startsWith(year.value))) && (place.value === 'all' || (place.value === 'unplaced' ? !p.place : p.place?.cityName === place.value))));
const months = computed(() => groupPhotos(filtered.value));
const years = computed(() => [...new Set(library.value.items.map(p => p.takenOn?.slice(0, 4) || 'unknown'))].sort((a, b) => b.localeCompare(a)));
const places = computed(() => [...new Set(library.value.items.flatMap(p => p.place?.cityName ? [p.place.cityName] : []))].sort((a, b) => a.localeCompare(b, 'zh-CN')));
const hasUnplaced = computed(() => library.value.items.some(p => !p.place));
function note(photo: PhotoMemory) { return library.value.groupNotes.find(n => n.key === photoGroupKey(photo))?.note; }
async function load() { busy.value = true; error.value = ''; try { const data = await api<PhotoLibrary>('/photos'); if (!disposed) library.value = data; } catch (e) { if (!disposed) error.value = errorText(e); } finally { if (!disposed) busy.value = false; } }
function openPhoto(photo: PhotoMemory, group?: PhotoMemory[]) { scroll = content.value?.scrollTop || 0; viewer.value = { photos: group || filtered.value.filter(p => photoGroupKey(p) === photoGroupKey(photo)), start: photo.mediaId }; }
async function closeViewer() { viewer.value = null; await nextTick(); if (content.value && mode.value === 'list') content.value.scrollTop = scroll; }
function edit(photo?: PhotoMemory) { if (!viewer.value) scroll = content.value?.scrollTop || 0; viewer.value = null; editing.value = photo; editor.value = true; }
async function saved() { editor.value = false; editing.value = undefined; await load(); await nextTick(); if (content.value && mode.value === 'list') content.value.scrollTop = scroll; }
function onMap(photo: PhotoMemory) { viewer.value = null; mode.value = 'map'; mapFocus.value = { ...photo }; }
async function setMode(value: 'list' | 'map') { if (value === mode.value) return; if (mode.value === 'list') scroll = content.value?.scrollTop || 0; mode.value = value; await nextTick(); if (value === 'list' && content.value) content.value.scrollTop = scroll; }
function choose(kind: 'year' | 'place', value: string) { if (kind === 'year') year.value = value; else place.value = value; filter.value = null; mapFocus.value = null; scroll = 0; if (content.value) content.value.scrollTop = 0; }
watch([year, place, mode], () => { if (mode.value === 'map') mapSeen.value = true; try { sessionStorage.setItem(stateKey, JSON.stringify({ year: year.value, place: place.value, mode: mode.value, scroll })); } catch {} });
onMounted(async () => { try { const state = JSON.parse(sessionStorage.getItem(stateKey) || 'null'); if (state) { year.value = typeof state.year === 'string' ? state.year : 'all'; place.value = typeof state.place === 'string' ? state.place : 'all'; mode.value = state.mode === 'map' ? 'map' : 'list'; scroll = Number(state.scroll) || 0; } } catch {} await load(); await nextTick(); if (content.value && mode.value === 'list') content.value.scrollTop = scroll; });
onBeforeUnmount(() => { disposed = true; try { sessionStorage.setItem(stateKey, JSON.stringify({ year: year.value, place: place.value, mode: mode.value, scroll: mode.value === 'list' ? content.value?.scrollTop || 0 : scroll })); } catch {} });
</script>
<template><section class="photo-memory-view" :class="{ 'is-map': mode === 'map' }"><header class="memory-heading"><div><p class="memory-eyebrow">LITTLE MOMENTS, REAL PLACES</p><h2>沿途的片刻</h2></div><button class="memory-add" @click="edit()">添加照片<AtlasIcon name="plus"/></button></header><div class="memory-toolbar"><div class="memory-segment" role="tablist" aria-label="回忆浏览方式"><button role="tab" :aria-selected="mode === 'list'" @click="setMode('list')">列表</button><button role="tab" :aria-selected="mode === 'map'" @click="setMode('map')">地图</button></div><div class="memory-filters"><button aria-haspopup="dialog" @click="filter = 'year'">{{ year === 'all' ? '全部年份' : year === 'unknown' ? '时间待补' : year }}<AtlasIcon name="chevronDown"/></button><button aria-haspopup="dialog" @click="filter = 'place'">{{ place === 'all' ? '全部地点' : place === 'unplaced' ? '地点待补' : place.replace(/市$/, '') }}<AtlasIcon name="chevronDown"/></button></div></div>
<p v-if="error" class="memory-error" role="alert">{{ error }}<button class="memory-text-button" @click="load">重试读取</button></p><p v-if="busy && !library.items.length" class="memory-panel-copy" role="status">正在翻开沿途的照片…</p>
<div ref="content" v-show="mode === 'list'" class="memory-content photo-wall"><div v-if="!busy && !filtered.length && !error" class="memory-empty"><AtlasIcon name="camera" :size="40"/><h3>{{ library.items.length ? '这里，还没有相片' : '把第一张照片，留在这里' }}</h3><p>{{ library.items.length ? '换个年份或地点，找找别处的片刻。' : '一张照片，一个地方。不必有标题，也不必写很长的故事。' }}</p><button v-if="library.items.length" class="memory-text-button" @click="year = 'all'; place = 'all'">查看全部照片</button><button v-else class="memory-text-button" @click="edit()">添加第一张照片</button></div>
<section v-for="month in months" :key="month.key" class="memory-month"><header class="memory-month-title"><h3>{{ month.title }}</h3><small>{{ month.key === 'undated' ? 'SOMETIME, SOMEWHERE' : 'COLLECTED MOMENTS' }}</small></header><section v-for="group in month.places" :key="group.key" class="memory-place"><header class="memory-place-heading"><AtlasIcon name="pin"/><h4>{{ group.title }}</h4><small>{{ group.photos.length }} 张照片</small></header><div class="memory-photo-grid"><figure v-for="photo in group.photos" :key="photo.mediaId" class="memory-photo" :class="{ wide: photo.media.width / photo.media.height > 1.8 }"><button class="memory-photo-open" :aria-label="'查看' + photoPlaceName(photo.place) + '，' + photoDate(photo.takenOn)" @click="openPhoto(photo)"><span class="memory-paper"><img :src="photo.media.previewUrl" :width="photo.media.width" :height="photo.media.height" :alt="photoPlaceName(photo.place)" loading="lazy"></span><span class="memory-photo-meta"><time>{{ photoDate(photo.takenOn) }}</time></span><span v-if="photo.note" class="memory-photo-note">{{ photo.note }}</span></button></figure></div><p v-if="group.photos[0] && note(group.photos[0])" class="memory-group-note">{{ note(group.photos[0]) }}</p></section></section><footer class="photo-library-footer"><RouterLink to="/journals">图文日记</RouterLink><small v-if="library.items.length">{{ library.items.length }} 张照片，慢慢留住沿途。</small></footer></div>
<PhotoMemoryMap v-if="mapSeen" v-show="mode === 'map'" :photos="filtered" :focus="mapFocus" @open="photos => photos[0] && openPhoto(photos[0], photos)"/>
<ModalSheet v-if="filter" :title="filter === 'year' ? '翻到哪一年？' : '看看哪个地方？'" @close="filter = null"><template v-if="filter === 'year'"><button class="memory-option" @click="choose('year', 'all')">全部年份</button><button v-for="value in years" :key="value" class="memory-option" @click="choose('year', value)">{{ value === 'unknown' ? '时间待补充' : value + ' 年' }}</button></template><template v-else><button class="memory-option" @click="choose('place', 'all')">全部地点</button><button v-for="value in places" :key="value" class="memory-option" @click="choose('place', value)">{{ value }}</button><button v-if="hasUnplaced" class="memory-option" @click="choose('place', 'unplaced')">地点待补充</button></template></ModalSheet>
<PhotoViewer v-if="viewer" :photos="viewer.photos" :start="viewer.start" :notes="library.groupNotes" @close="closeViewer" @edit="edit" @map="onMap" @remove="viewer = null; removeKey = mutationId(); removeError = ''; removing = $event"/>
<PhotoEditor v-if="editor" :photo="editing" :notes="library.groupNotes" :max-bytes="library.uploadMaxBytes" @close="editor = false; editing = undefined" @saved="saved"/>
<ModalSheet v-if="removing" title="从回忆中移除这张照片？" :busy="removeBusy" @close="removing = null"><p v-if="removeError" class="memory-error" role="alert">{{ removeError }}</p><p class="memory-panel-copy">{{ removing.diaryId ? '照片仍会保留在原日记中。' : '这张独立照片及其文件会被删除，请确认已保留需要的原图。' }}</p><template #footer><button class="memory-primary" :disabled="removeBusy" @click="removePhoto">{{ removeBusy ? '正在移除…' : '确认移出回忆' }}</button></template></ModalSheet></section></template>
